`;function tN(n){let r="";for(let s of n){let c=s.codePointAt(0);c>=65&&c<=90?r+=String.fromCharCode(c+32):c>=97&&c<=122||c>=48&&c<=57||s==="-"||s==="_"||s==="+"||s==="."?r+=s:r+="_"}return r.length>64&&(r=r.slice(0,64)),r=r.replace(/^[.\-+]+/,"").replace(/\.+$/,""),r}function BSe(n){let r="";for(let s of n){let c=s.codePointAt(0);r+=c>=33&&c<=126&&s!==";"?s:"_"}return r}function r8t(n,r,s){let c=n.map(w=>w.slice(0,s)),p=new Set(c),m=new Set(r),b=new Map,y=[];for(let w of c){let T=w;if(m.has(T)){let C=b.get(w)||2;for(;;C++){let L="_"+C;if(T=w.slice(0,s-L.length)+L,!p.has(T)&&!m.has(T))break}b.set(w,C)}y.push(T),m.add(T)}return y}var Gse=n=>n.trim().replace(/\s/g,"_"),Wse=class{constructor(){this.names=[],this.nmap=new Map,this.texts=[],this.tmap=new Map}idOf(n){let r=n.toLowerCase(),s=this.nmap.get(r);return s===void 0&&(s=this.names.length,this.nmap.set(r,s),this.names.push(r)),s}textOf(n){let r=this.tmap.get(n);return r===void 0&&(r=this.texts.length,this.tmap.set(n,r),this.texts.push(n)),r}sys(n,r,s=""){n.set(this.idOf("."+r),s)}text(n,r,s){s&&n.set(this.idOf("."+r),String(this.textOf(s.replace(/[\r\n]+/g," ").toUpperCase())))}tables(){return`
